//! Reader fixtures for positioned-model tests (`test-api`).
//!
//! Fixtures live in `context-read/tests/fixtures/v3` (authoritative manifest
//! `scenarios.json`, generated by the `ngrams` oracle); they are read from
//! disk so model and navigation tests need no dependency on `ngrams` or
//! `legacy`. The insert lane `v3/insert` holds one oracle graph per insert
//! case (insert plan rev 3, task 3.1.1); its manifest is enumerated from the
//! v3 fixtures by [`insert_manifest`]. The read lane `v3/read` holds one
//! oracle graph per read of a multi-input scenario (reader plan §9.1); its
//! manifest is derived from the v3 manifest by [`read_manifest`].

use std::{
    collections::{
        BTreeMap,
        BTreeSet,
    },
    path::{
        Path,
        PathBuf,
    },
};

use serde::{
    Deserialize,
    Serialize,
};

use super::{
    PositionedGraph,
    interchange::{
        PositionedGraphData,
        PositionedGraphSnapshot,
    },
};
use crate::{
    BaseGraphKind,
    Token,
};

/// One manifest entry: a fixture name and the corpus it is generated from.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
pub struct Scenario {
    pub name: String,
    pub inputs: Vec<String>,
}

/// Directory of the reader fixtures.
pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../context-read/tests/fixtures/v3")
}

/// Directory of the insert lane (one oracle graph per insert case).
pub fn insert_dir() -> PathBuf {
    fixtures_dir().join("insert")
}

/// Directory of the read lane (one oracle graph per read).
pub fn read_dir() -> PathBuf {
    fixtures_dir().join("read")
}

fn read(path: PathBuf) -> Vec<u8> {
    std::fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// The manifest `scenarios.json` of the lane in `dir`.
pub fn manifest(dir: &Path) -> Vec<Scenario> {
    let scenarios: Vec<Scenario> = serde_json::from_slice(&read(dir.join("scenarios.json")))
        .unwrap_or_else(|error| panic!("{}: {error}", dir.display()));
    assert!(!scenarios.is_empty(), "{}: empty manifest", dir.display());
    scenarios
}

/// The fixture `name` of the lane in `dir`, decoded and structurally
/// validated.
fn snapshot(
    dir: &Path,
    name: &str,
) -> PositionedGraphSnapshot {
    let fixture: PositionedGraphSnapshot =
        serde_json::from_slice(&read(dir.join(format!("{name}.json"))))
            .unwrap_or_else(|error| panic!("{name}: {error}"));
    fixture
        .validate()
        .unwrap_or_else(|error| panic!("{name}: {error}"));
    fixture
}

/// Every manifest fixture as `(name, snapshot)`, decoded and structurally
/// validated. Panics on any I/O, decoding or validation error.
pub fn fixture_snapshots() -> Vec<(String, PositionedGraphSnapshot)> {
    manifest(&fixtures_dir())
        .into_iter()
        .map(|Scenario { name, .. }| {
            let fixture = snapshot(&fixtures_dir(), &name);
            (name, fixture)
        })
        .collect()
}

/// A reader fixture converted to a [`PositionedGraph`].
pub struct FixtureGraph {
    pub name: String,
    pub corpus: Vec<String>,
    pub graph: PositionedGraph<BaseGraphKind>,
    /// Fixture vertex key → token; the only way tests address vertices.
    pub names: BTreeMap<String, Token>,
}

impl FixtureGraph {
    fn new(
        name: String,
        fixture: PositionedGraphSnapshot,
    ) -> Self {
        let (graph, names) = PositionedGraph::from_interchange_named(&fixture.graph)
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        Self {
            name,
            corpus: fixture.corpus,
            graph,
            names,
        }
    }
}

/// Every manifest fixture, converted with
/// [`PositionedGraph::from_interchange_named`].
pub fn fixture_graphs() -> Vec<FixtureGraph> {
    fixture_snapshots()
        .into_iter()
        .map(|(name, fixture)| FixtureGraph::new(name, fixture))
        .collect()
}

/// Every substring of at least two atoms of a vertex string of `graph` that
/// is not itself a vertex, sorted by `(width, string)`: the insert queries
/// of one fixture.
///
/// Asserts that each has exactly one minimal host occurrence (G5): an
/// occurrence `(v, x)` that lies in no child occurrence of `v`.
pub fn insert_queries(graph: &PositionedGraphData) -> Vec<String> {
    let vertices: BTreeMap<&str, Vec<char>> = graph
        .vertices
        .keys()
        .map(|key| (key.as_str(), key.chars().collect()))
        .collect();
    let mut queries = BTreeSet::new();
    for chars in vertices.values() {
        for start in 0..chars.len() {
            for end in start + 2..=chars.len() {
                let query: String = chars[start..end].iter().collect();
                if !vertices.contains_key(query.as_str()) {
                    queries.insert(query);
                }
            }
        }
    }
    let mut queries: Vec<String> = queries.into_iter().collect();
    queries.sort_by_key(|query| (query.chars().count(), query.clone()));
    for query in &queries {
        let query_chars: Vec<char> = query.chars().collect();
        let width = query_chars.len();
        let hosts: Vec<(&str, usize)> = vertices
            .iter()
            .filter(|(_, chars)| chars.len() > width)
            .flat_map(|(&key, chars)| {
                let cover = &graph.vertices[key];
                (0..=chars.len() - width)
                    .filter(|&x| chars[x..x + width] == query_chars[..])
                    .filter(|&x| {
                        !cover.iter().any(|(offset, child)| {
                            *offset <= x && x + width <= offset + child.chars().count()
                        })
                    })
                    .map(move |x| (key, x))
            })
            .collect();
        assert_eq!(hosts.len(), 1, "{query:?}: minimal hosts {hosts:?} (G5)");
    }
    queries
}

/// The insert lane manifest, enumerated from the current v3 fixtures: for
/// every scenario and each of its [`insert_queries`] (numbered from 1), the
/// entry `<scenario>__<k>` with inputs `corpus + [query]`.
pub fn insert_manifest() -> Vec<Scenario> {
    fixture_snapshots()
        .into_iter()
        .flat_map(|(name, fixture)| {
            insert_queries(&fixture.graph)
                .into_iter()
                .enumerate()
                .map(move |(k, query)| {
                    let mut inputs = fixture.corpus.clone();
                    inputs.push(query);
                    Scenario {
                        name: format!("{name}__{}", k + 1),
                        inputs,
                    }
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

/// One insert case: the base graph, the query to insert and the expected
/// oracle graph of the base corpus plus the query.
pub struct InsertCase {
    /// `<scenario>__<k>`.
    pub name: String,
    pub base: FixtureGraph,
    pub query: String,
    pub expected: FixtureGraph,
}

/// Every entry of the insert lane manifest, with its base v3 fixture.
pub fn insert_cases() -> Vec<InsertCase> {
    let mut bases: BTreeMap<String, PositionedGraphSnapshot> = BTreeMap::new();
    manifest(&insert_dir())
        .into_iter()
        .map(|Scenario { name, mut inputs }| {
            let (scenario, _) = name
                .rsplit_once("__")
                .unwrap_or_else(|| panic!("{name}: not <scenario>__<k>"));
            let base = bases
                .entry(scenario.to_string())
                .or_insert_with(|| snapshot(&fixtures_dir(), scenario))
                .clone();
            let query = inputs.pop().unwrap_or_else(|| panic!("{name}: no inputs"));
            assert_eq!(inputs, base.corpus, "{name}: inputs must extend the base corpus");
            let expected = snapshot(&insert_dir(), &name);
            InsertCase {
                base: FixtureGraph::new(scenario.to_string(), base),
                query,
                expected: FixtureGraph::new(name.clone(), expected),
                name,
            }
        })
        .collect()
}

/// The read lane manifest, derived from the v3 manifest: for every scenario
/// with `n ≥ 2` inputs and every `k ∈ 1..=n`, the entry `<scenario>__<k>`
/// with inputs `inputs[..k]`.
pub fn read_manifest() -> Vec<Scenario> {
    manifest(&fixtures_dir())
        .into_iter()
        .filter(|scenario| scenario.inputs.len() >= 2)
        .flat_map(|Scenario { name, inputs }| {
            (1..=inputs.len())
                .map(|k| Scenario {
                    name: format!("{name}__{k}"),
                    inputs: inputs[..k].to_vec(),
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

/// One read case: the oracle graph of the earlier inputs (`None` for the
/// first read), the input to read and the oracle graph after it.
pub struct ReadCase {
    /// `<scenario>__<k>`.
    pub name: String,
    pub base: Option<PositionedGraphSnapshot>,
    pub input: String,
    pub expected: PositionedGraphSnapshot,
}

/// Every entry of the read lane manifest; case `k` reads into the graph of
/// case `k − 1`.
pub fn read_cases() -> Vec<ReadCase> {
    let mut previous: Option<(String, PositionedGraphSnapshot)> = None;
    manifest(&read_dir())
        .into_iter()
        .map(|Scenario { name, mut inputs }| {
            let (scenario, k) = name
                .rsplit_once("__")
                .and_then(|(scenario, k)| Some((scenario.to_string(), k.parse::<usize>().ok()?)))
                .unwrap_or_else(|| panic!("{name}: not <scenario>__<k>"));
            assert_eq!(inputs.len(), k, "{name}: inputs must be the first {k} inputs");
            let expected = snapshot(&read_dir(), &name);
            assert_eq!(expected.corpus, inputs, "{name}: corpus must equal the inputs");
            let input = inputs.pop().unwrap_or_else(|| panic!("{name}: no inputs"));
            let base = (k > 1).then(|| {
                let (previous_name, base) =
                    previous.take().unwrap_or_else(|| panic!("{name}: no previous case"));
                assert_eq!(
                    previous_name,
                    format!("{scenario}__{}", k - 1),
                    "{name}: cases of a scenario must be consecutive"
                );
                assert_eq!(base.corpus, inputs, "{name}: base corpus must be the earlier inputs");
                base
            });
            previous = Some((name.clone(), expected.clone()));
            ReadCase {
                name,
                base,
                input,
                expected,
            }
        })
        .collect()
}
